-- Fresh MySQL 8.0+ initialization only. Existing databases use docs/mysql-upgrade-v2-006.sql.
CREATE TABLE IF NOT EXISTS app_user (id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,display_name VARCHAR(50) NOT NULL,role VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ENABLED',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_catalog (id BIGINT AUTO_INCREMENT PRIMARY KEY,service_name VARCHAR(100) NOT NULL UNIQUE,display_name VARCHAR(100) NOT NULL,owner_name VARCHAR(50),current_version VARCHAR(30),runtime_status VARCHAR(20));
CREATE TABLE IF NOT EXISTS knowledge_base (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(500),status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',created_by BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS knowledge_document (id BIGINT AUTO_INCREMENT PRIMARY KEY,kb_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,current_version_id BIGINT,created_by BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_document_kb FOREIGN KEY (kb_id) REFERENCES knowledge_base(id));
CREATE TABLE IF NOT EXISTS document_version (id BIGINT AUTO_INCREMENT PRIMARY KEY,document_id BIGINT NOT NULL,version_no VARCHAR(30) NOT NULL,original_name VARCHAR(255) NOT NULL,file_type VARCHAR(20) NOT NULL,file_size BIGINT NOT NULL,checksum VARCHAR(64) NOT NULL,storage_path VARCHAR(500) NOT NULL,process_status VARCHAR(20) NOT NULL DEFAULT 'PENDING',publish_status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',effective_at TIMESTAMP NULL,chunk_count INT NOT NULL DEFAULT 0,failure_reason VARCHAR(1000),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at TIMESTAMP NULL,CONSTRAINT uk_document_version UNIQUE (document_id,version_no),CONSTRAINT fk_version_document FOREIGN KEY (document_id) REFERENCES knowledge_document(id));
CREATE TABLE IF NOT EXISTS document_chunk_ref (id BIGINT AUTO_INCREMENT PRIMARY KEY,version_id BIGINT NOT NULL,vector_id VARCHAR(100) NOT NULL UNIQUE,chunk_index INT NOT NULL,page_number INT NULL,content LONGTEXT NOT NULL,CONSTRAINT uk_version_chunk UNIQUE (version_id,chunk_index),CONSTRAINT fk_chunk_version FOREIGN KEY (version_id) REFERENCES document_version(id));
CREATE TABLE IF NOT EXISTS app_seed (seed_key VARCHAR(100) PRIMARY KEY);
CREATE TABLE IF NOT EXISTS conversation (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,title VARCHAR(120) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_conversation_user FOREIGN KEY (user_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS chat_message (id BIGINT AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT NOT NULL,role VARCHAR(20) NOT NULL,content LONGTEXT NOT NULL,kb_id BIGINT NULL,confidence_level VARCHAR(20),evidence_sufficiency VARCHAR(30),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_message_conversation FOREIGN KEY (conversation_id) REFERENCES conversation(id),CONSTRAINT fk_message_kb FOREIGN KEY (kb_id) REFERENCES knowledge_base(id));
CREATE TABLE IF NOT EXISTS message_citation (id BIGINT AUTO_INCREMENT PRIMARY KEY,message_id BIGINT NOT NULL,version_id BIGINT NOT NULL,vector_id VARCHAR(100) NOT NULL,quote_text LONGTEXT NOT NULL,page_number INT,title VARCHAR(200),version_no VARCHAR(30),CONSTRAINT fk_citation_message FOREIGN KEY (message_id) REFERENCES chat_message(id),CONSTRAINT fk_citation_version FOREIGN KEY (version_id) REFERENCES document_version(id));
CREATE TABLE IF NOT EXISTS message_feedback (id BIGINT AUTO_INCREMENT PRIMARY KEY,message_id BIGINT NOT NULL,user_id BIGINT NOT NULL,rating VARCHAR(10) NOT NULL,comment_text VARCHAR(500),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_message_feedback UNIQUE (message_id,user_id),CONSTRAINT fk_feedback_message FOREIGN KEY (message_id) REFERENCES chat_message(id),CONSTRAINT fk_feedback_user FOREIGN KEY (user_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS release_record (id BIGINT AUTO_INCREMENT PRIMARY KEY,service_name VARCHAR(100) NOT NULL,version_no VARCHAR(30) NOT NULL,environment VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL,released_at TIMESTAMP NOT NULL,summary VARCHAR(500));
CREATE TABLE IF NOT EXISTS incident_record (id BIGINT AUTO_INCREMENT PRIMARY KEY,service_name VARCHAR(100) NOT NULL,symptom VARCHAR(500) NOT NULL,root_cause VARCHAR(1000),resolution VARCHAR(1000),status VARCHAR(20) NOT NULL,occurred_at TIMESTAMP NOT NULL,resolved_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS diagnosis_record (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,kb_id BIGINT NOT NULL,service_name VARCHAR(100) NOT NULL,symptom VARCHAR(1000) NOT NULL,error_context LONGTEXT,result_content LONGTEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',evidence_snapshot LONGTEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_diagnosis_user FOREIGN KEY (user_id) REFERENCES app_user(id),CONSTRAINT fk_diagnosis_kb FOREIGN KEY (kb_id) REFERENCES knowledge_base(id));
CREATE TABLE IF NOT EXISTS knowledge_gap (id BIGINT AUTO_INCREMENT PRIMARY KEY,kb_id BIGINT NOT NULL,normalized_question VARCHAR(1000) NOT NULL,normalized_question_hash BINARY(32) GENERATED ALWAYS AS (UNHEX(SHA2(normalized_question,256))) STORED,sample_question VARCHAR(1000) NOT NULL,source_type VARCHAR(30) NOT NULL DEFAULT 'NO_EVIDENCE',priority VARCHAR(10) NOT NULL DEFAULT 'MEDIUM',occurrence_count INT NOT NULL DEFAULT 1,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',processing_note VARCHAR(500),processing_at TIMESTAMP NULL,processing_by BIGINT NULL,resolution_type VARCHAR(30),resolution_note VARCHAR(500),first_seen_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,resolved_at TIMESTAMP NULL,resolved_by BIGINT NULL,last_verification_result VARCHAR(30),CONSTRAINT uk_gap_question UNIQUE (kb_id,normalized_question_hash),CONSTRAINT fk_gap_kb FOREIGN KEY (kb_id) REFERENCES knowledge_base(id),CONSTRAINT fk_gap_processing_user FOREIGN KEY (processing_by) REFERENCES app_user(id),CONSTRAINT fk_gap_resolved_user FOREIGN KEY (resolved_by) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS gap_occurrence (id BIGINT AUTO_INCREMENT PRIMARY KEY,gap_id BIGINT NOT NULL,conversation_id BIGINT NULL,question_message_id BIGINT NULL,assistant_message_id BIGINT NULL,feedback_id BIGINT NULL,question VARCHAR(1000) NOT NULL,source_type VARCHAR(30) NOT NULL,evidence_summary VARCHAR(500),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_gap_occurrence_feedback UNIQUE (feedback_id),CONSTRAINT fk_occurrence_gap FOREIGN KEY (gap_id) REFERENCES knowledge_gap(id),CONSTRAINT fk_occurrence_conversation FOREIGN KEY (conversation_id) REFERENCES conversation(id),CONSTRAINT fk_occurrence_question FOREIGN KEY (question_message_id) REFERENCES chat_message(id),CONSTRAINT fk_occurrence_assistant FOREIGN KEY (assistant_message_id) REFERENCES chat_message(id),CONSTRAINT fk_occurrence_feedback FOREIGN KEY (feedback_id) REFERENCES message_feedback(id));
CREATE TABLE IF NOT EXISTS gap_verification (id BIGINT AUTO_INCREMENT PRIMARY KEY,gap_id BIGINT NOT NULL,question VARCHAR(1000) NOT NULL,evidence_sufficient BOOLEAN NOT NULL,result VARCHAR(30) NOT NULL,retrieval_summary VARCHAR(1000),operator_id BIGINT NOT NULL,notes VARCHAR(500),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_verification_gap FOREIGN KEY (gap_id) REFERENCES knowledge_gap(id),CONSTRAINT fk_verification_operator FOREIGN KEY (operator_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS tool_call_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,tool_name VARCHAR(80) NOT NULL,parameter_summary VARCHAR(500),result_count INT NOT NULL,success BOOLEAN NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_tool_audit_user FOREIGN KEY (user_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS diagnosis_tool_call_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,diagnosis_request_id VARCHAR(50) NOT NULL,tool_name VARCHAR(80) NOT NULL,model_requested BOOLEAN NOT NULL,authorization_granted BOOLEAN NOT NULL,success BOOLEAN NOT NULL,failure_category VARCHAR(50),duration_ms BIGINT NOT NULL,result_size INT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_diagnosis_tool_audit_user FOREIGN KEY (user_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS sql_query_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY,request_id VARCHAR(50) NOT NULL,user_id BIGINT NOT NULL,question VARCHAR(500) NOT NULL,generated_sql VARCHAR(4000),validation_status VARCHAR(20) NOT NULL,execution_status VARCHAR(20) NOT NULL,latency_ms BIGINT,row_count INT NOT NULL DEFAULT 0,failure_reason VARCHAR(1000),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_sql_audit_user FOREIGN KEY (user_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS ai_call_log (id BIGINT AUTO_INCREMENT PRIMARY KEY,request_id VARCHAR(50) NOT NULL,user_id BIGINT NOT NULL,scene VARCHAR(40) NOT NULL,model_name VARCHAR(80),latency_ms BIGINT,input_tokens INT NOT NULL DEFAULT 0,output_tokens INT NOT NULL DEFAULT 0,token_estimated BOOLEAN NOT NULL DEFAULT TRUE,status VARCHAR(20) NOT NULL,error_code VARCHAR(50),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_ai_log_user FOREIGN KEY (user_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS ai_provider_call_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(40) NOT NULL,operation VARCHAR(40) NOT NULL,success BOOLEAN NOT NULL,failure_category VARCHAR(40),retry_count INT NOT NULL DEFAULT 0,circuit_state VARCHAR(20),latency_ms BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS version_semantic_compare_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY,old_version_id BIGINT NOT NULL,new_version_id BIGINT NOT NULL,provider VARCHAR(40) NOT NULL,operation VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,failure_category VARCHAR(60),latency_ms BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_semantic_audit_old FOREIGN KEY (old_version_id) REFERENCES document_version(id),CONSTRAINT fk_semantic_audit_new FOREIGN KEY (new_version_id) REFERENCES document_version(id));
